package com.wordlock.test;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.widget.*;
public class MainActivity extends Activity {
public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(40,60,40,40);TextView t=new TextView(this);t.setText("WordLock v0.2\n\nAna ekran kelime widget'ı\nWidget'ı saatin altına taşı. Dokunarak da kelime değiştirebilirsin.");t.setTextSize(20);l.addView(t);Button a=new Button(this);a.setText("Widget ekle");a.setOnClickListener(v->{AppWidgetManager m=AppWidgetManager.getInstance(this);if(m.isRequestPinAppWidgetSupported())m.requestPinAppWidget(new ComponentName(this,WordWidget.class),null,null);else Toast.makeText(this,"Ana ekrana uzun bas ve Widget'lar menüsünü aç",1).show();});l.addView(a);Button s=new Button(this);s.setText("Otomatik kelime değişimini başlat");s.setOnClickListener(v->{startForegroundService(new Intent(this,WordService.class));Toast.makeText(this,"Otomatik değişim etkin",0).show();});l.addView(s);Button q=new Button(this);q.setText("Otomatik değişimi durdur");q.setOnClickListener(v->stopService(new Intent(this,WordService.class)));l.addView(q);setContentView(l);}
}